/* GreenHaven — care topics (part 3: pests, problems, environment, safety) */
(function (K) {
  'use strict';
  const P = t => K.TOPICS.push(t);

P({ id:'pests-mites', cat:'pest',
  kw:{ en:['spider mite','mites','webbing','web on plant','tiny red','speckled leaves','stippling'],
       uz:['orgimchak kana','o‘rgimchak kana','kana','to‘r','mayda qizil','nuqtali barg'],
       ru:['паутинн','клещ','паутин','мелкие красные','крапчат'],
       zh:['红蜘蛛','螨','蛛网','叶螨','白点','细丝'],
       ar:['عنكبوت أحمر','العث','خيوط','سوس','نقاط صغيرة'] },
  title:{ en:'Spider mites', uz:'O‘rgimchak kanalar', ru:'Паутинный клещ', zh:'红蜘蛛（叶螨）', ar:'العنكبوت الأحمر' },
  body:{
    en:['Spider mites are almost invisible but devastating. They thrive in hot, dry, still air, which is exactly what central heating creates.',
        '- Look for fine pale stippling on the upper leaf surface and delicate webbing where leaf meets stem.',
        '- Isolate the plant immediately — mites spread to every neighbour within days.',
        '- Take it to a shower or sink and blast every surface, especially leaf undersides, with lukewarm water.',
        '- Spray thoroughly with insecticidal soap or a 1:1:100 mix of mild soap, neem oil and water. Cover the undersides.',
        '- Repeat every five days for three weeks. This breaks the egg cycle — a single treatment never works.',
        '- Raise the humidity afterwards. Mites hate damp air, so a humidifier is the best long-term defence.'],
    uz:['O‘rgimchak kana deyarli ko‘rinmaydi, lekin juda zararli. U issiq, quruq va turg‘un havoda ko‘payadi — markaziy isitish aynan shunday muhit yaratadi.',
        '- Barg ustida mayda och nuqtalarni va barg bilan poya tutashgan joyda nozik to‘rni qidiring.',
        '- O‘simlikni darhol ajratib qo‘ying — kana bir necha kunda barcha qo‘shnisiga tarqaladi.',
        '- Dush yoki rakovinaga olib boring va iliq suv bilan har bir yuzani, ayniqsa barg ostini kuchli yuvib tashlang.',
        '- Insektitsid sovun yoki 1:1:100 nisbatda yumshoq sovun, nim moyi va suv aralashmasini puxta purkang. Barg ostini albatta qoplang.',
        '- Uch hafta davomida har besh kunda takrorlang. Bu tuxum siklini uzadi — bir martalik ishlov hech qachon kifoya qilmaydi.',
        '- Keyin namlikni oshiring. Kana nam havoni yoqtirmaydi, shuning uchun namlagich eng yaxshi uzoq muddatli himoya.'],
    ru:['Паутинный клещ почти не виден, но крайне опасен. Он процветает в жарком, сухом и неподвижном воздухе — именно это создаёт отопление.',
        '- Ищите мелкую светлую крапчатость на верхней стороне листа и тонкую паутинку в пазухах.',
        '- Немедленно изолируйте растение — за несколько дней клещ перейдёт на всех соседей.',
        '- Отнесите в душ или раковину и тщательно смойте тёплой водой все поверхности, особенно изнанку листьев.',
        '- Обильно опрыскайте инсектицидным мылом или смесью мягкого мыла, масла нима и воды 1:1:100. Обязательно снизу.',
        '- Повторяйте каждые пять дней в течение трёх недель: это разрывает цикл яиц — одна обработка не помогает никогда.',
        '- Затем поднимите влажность. Клещ не переносит влажный воздух, поэтому увлажнитель — лучшая долгосрочная защита.'],
    zh:['红蜘蛛几乎看不见，但危害极大。它喜欢高温、干燥、不流通的空气——正是暖气房的典型环境。',
        '- 检查叶面上细密的浅色小斑点，以及叶柄与茎交接处的细网。',
        '- 立刻隔离该植株——几天之内它就会传染给所有邻居。',
        '- 搬到淋浴间或水槽，用温水冲洗每一处表面，尤其是叶背。',
        '- 用杀虫皂，或按 1:1:100 调配温和皂液、印楝油与水，彻底喷洒，务必喷到叶背。',
        '- 每五天重复一次，持续三周。这样才能打断虫卵周期——只喷一次永远无效。',
        '- 之后请提高湿度。螨虫怕潮湿空气，加湿器是最好的长期防线。'],
    ar:['العنكبوت الأحمر يكاد لا يُرى لكنه مدمّر. يزدهر في الهواء الحار الجاف الساكن، وهو تمامًا ما توفّره التدفئة المركزية.',
        '- ابحث عن تنقيط فاتح دقيق على سطح الورقة العلوي وخيوط رفيعة حيث تلتقي الورقة بالساق.',
        '- اعزل النبتة فورًا — فالعث ينتقل إلى كل جيرانها خلال أيام.',
        '- انقلها إلى الدش أو الحوض واغسل كل سطح بماء فاتر، وخصوصًا الوجه السفلي للأوراق.',
        '- رُشّ جيدًا بصابون مبيد أو بخليط ١:١:١٠٠ من صابون لطيف وزيت النيم والماء، مع تغطية الأسطح السفلية.',
        '- كرّر كل خمسة أيام لمدة ثلاثة أسابيع لكسر دورة البيض — فالمعالجة الواحدة لا تنجح أبدًا.',
        '- ثم ارفع الرطوبة. العث يكره الهواء الرطب، لذا فالمرطّب أفضل دفاع على المدى الطويل.'] } });

P({ id:'pests-gnats', cat:'pest',
  kw:{ en:['fungus gnat','gnats','flies','small flies','soil flies','fruit flies plant'],
       uz:['tuproq pashsha','pashsha','mayda pashsha','chivin'],
       ru:['мошк','мошек','мошка','почвенн','сциарид','мушк','мелкие мухи','дрозофил'],
       zh:['小黑飞','蕈蚊','飞虫','小飞虫','土里虫'],
       ar:['ذباب','بعوض','حشرات صغيره تطير','ذباب الفطر'] },
  title:{ en:'Fungus gnats', uz:'Tuproq pashshalari', ru:'Почвенные мошки', zh:'小黑飞（蕈蚊）', ar:'ذباب الفطر' },
  body:{
    en:['Those little black flies are harmless to you but their larvae eat young roots. They appear for one reason: the top of the soil stays wet.',
        '- Let the top 3–4 cm dry out completely between waterings. This alone stops the breeding cycle.',
        '- Cover the surface with 1 cm of sand, grit or decorative gravel so the females cannot reach the compost to lay eggs.',
        '- Hang yellow sticky traps to catch the flying adults — they show you whether the infestation is shrinking.',
        '- Water from below for a few weeks so the surface never gets wet at all.',
        '- For a heavy infestation, drench the soil with Bacillus thuringiensis israelensis (mosquito bits) — it kills larvae and is harmless to plants and pets.',
        '- It usually takes three to four weeks to clear completely. Patience and dry topsoil do most of the work.'],
    uz:['Bu mayda qora pashshalar siz uchun zararsiz, lekin ularning qurti yosh ildizni yeydi. Ular bitta sabab bilan paydo bo‘ladi: tuproq yuzasi doim nam.',
        '- Sug‘orishlar orasida yuqori 3–4 sm butunlay qurishiga imkon bering. Faqat shuning o‘zi ko‘payish siklini to‘xtatadi.',
        '- Yuzani 1 sm qum, shag‘al yoki dekorativ toshcha bilan qoplang, shunda urg‘ochilari tuxum qo‘yish uchun tuproqqa yeta olmaydi.',
        '- Uchayotgan kattalarini ushlash uchun sariq yopishqoq tuzoqlar osing — ular zararlanish kamayayotganini ko‘rsatadi.',
        '- Bir necha hafta pastdan sug‘oring, shunda yuza umuman namlanmaydi.',
        '- Kuchli zararlanishda tuproqni Bacillus thuringiensis israelensis bilan sug‘oring — u qurtni o‘ldiradi, o‘simlik va hayvonlarga zararsiz.',
        '- Odatda to‘liq tozalanish uch-to‘rt hafta oladi. Asosiy ishni sabr va quruq yuza qatlami qiladi.'],
    ru:['Эти чёрные мошки безвредны для вас, но их личинки едят молодые корни. Появляются они по одной причине: верх грунта постоянно влажный.',
        '- Давайте верхним 3–4 см полностью просыхать между поливами. Одно это разрывает цикл размножения.',
        '- Засыпьте поверхность слоем песка или мелкого гравия в 1 см, чтобы самки не добрались до грунта для кладки.',
        '- Повесьте жёлтые клейкие ловушки для взрослых особей — по ним видно, уменьшается ли заражение.',
        '- Несколько недель поливайте снизу, чтобы поверхность вообще не намокала.',
        '- При сильном заражении пролейте грунт Bacillus thuringiensis israelensis — он убивает личинок и безопасен для растений и питомцев.',
        '- Полная очистка обычно занимает три-четыре недели. Основную работу делают терпение и сухой верхний слой.'],
    zh:['那些小黑飞对人无害，但幼虫会啃食嫩根。它们出现只有一个原因：表土长期潮湿。',
        '- 两次浇水之间让表层 3–4 厘米彻底干透，仅此一项就能打断繁殖循环。',
        '- 在土面铺 1 厘米厚的细砂、颗粒或装饰石，让雌虫无法接触基质产卵。',
        '- 挂黄色粘虫板捕捉成虫——也能直观看出虫情是否在减少。',
        '- 连续几周改为底部浸盆浇水，让表土完全不见水。',
        '- 虫害严重时，用苏云金杆菌以色列亚种（BTI）灌根——专杀幼虫，对植物和宠物无害。',
        '- 通常需要三到四周才能彻底根除。耐心加上干燥的表土，已经完成了大部分工作。'],
    ar:['هذا الذباب الأسود الصغير غير ضار بك، لكن يرقاته تأكل الجذور الفتية. ويظهر لسبب واحد: بقاء سطح التربة رطبًا.',
        '- اترك أعلى ٣–٤ سم تجفّ تمامًا بين الريّات. هذا وحده يوقف دورة التكاثر.',
        '- غطِّ السطح بطبقة سماكتها ١ سم من الرمل أو الحصى أو الحصى الزخرفي كي لا تصل الإناث إلى التربة لوضع البيض.',
        '- علّق مصائد لاصقة صفراء لالتقاط البالغات الطائرة — وهي تُظهر لك ما إذا كانت الإصابة تتراجع.',
        '- اسقِ من الأسفل لبضعة أسابيع كي لا يبتلّ السطح إطلاقًا.',
        '- عند الإصابة الشديدة، اسقِ التربة ببكتيريا Bacillus thuringiensis israelensis — تقتل اليرقات وهي غير ضارة بالنبات والحيوانات الأليفة.',
        '- عادة يستغرق التخلّص الكامل ثلاثة إلى أربعة أسابيع. والصبر وجفاف السطح يقومان بمعظم العمل.'] } });

P({ id:'pests-mealy', cat:'pest',
  kw:{ en:['mealybug','mealy','white fluffy','cotton','scale','aphid','sticky leaves','honeydew','bugs'],
       uz:['un qurt','oq paxta','shilimshiq barg','shira','qalqondor','hasharot'],
       ru:['мучнист','червец','червец','белый пушок','щитовк','тля','тли','липк','насеком'],
       zh:['介壳虫','粉蚧','白色棉絮','蚜虫','叶片发黏','虫'],
       ar:['البق الدقيقي','قطن أبيض','حشرة قشرية','المنّ','أوراق لزجة','حشرات'] },
  title:{ en:'Mealybugs, scale and aphids', uz:'Un qurtlari, qalqondorlar va shiralar', ru:'Мучнистый червец, щитовка и тля', zh:'粉蚧、介壳虫与蚜虫', ar:'البق الدقيقي والحشرات القشرية والمنّ' },
  body:{
    en:['These three sap-suckers are treated the same way. The sticky residue on leaves and furniture is their honeydew, and it is often noticed first.',
        '- Mealybugs look like tiny white cotton tufts in leaf joints. Scale are small brown limpet-like bumps on stems. Aphids cluster on new growth.',
        '- Isolate the plant. All three spread fast and easily reach neighbours.',
        '- Dab each insect directly with a cotton bud dipped in 70% isopropyl alcohol — it dissolves their waxy shell instantly.',
        '- Then spray the whole plant with insecticidal soap or diluted neem oil, covering stems, leaf undersides and the soil surface.',
        '- Repeat weekly for a month. Crawlers hatch continuously, so one treatment always leaves survivors.',
        '- Wipe down the pot, saucer and shelf too — eggs survive off the plant.',
        '- Check new purchases carefully and keep them apart for two weeks. Nearly every infestation arrives on a new plant.'],
    uz:['Bu uchala shira so‘ruvchi bir xil davolanadi. Barg va mebeldagi yopishqoq qoldiq — ularning shirasi, odatda birinchi bo‘lib shu seziladi.',
        '- Un qurtlari barg bo‘g‘imlarida mayda oq paxta bo‘lagiga o‘xshaydi. Qalqondorlar poyada jigarrang do‘ngchalar. Shiralar yangi o‘simtalarda to‘planadi.',
        '- O‘simlikni ajrating. Uchalasi ham tez tarqaladi va qo‘shnilariga osongina o‘tadi.',
        '- Har bir hasharotni 70% izopropil spirtga botirilgan paxta tayoqcha bilan to‘g‘ridan-to‘g‘ri arting — bu ularning mumli qobig‘ini bir zumda eritadi.',
        '- So‘ng butun o‘simlikni insektitsid sovun yoki suyultirilgan nim moyi bilan purkang: poya, barg osti va tuproq yuzasini qoplang.',
        '- Bir oy davomida haftasiga takrorlang. Qurtlar uzluksiz chiqib turadi, shuning uchun bir ishlov doim tirik qolganlarni qoldiradi.',
        '- Tuvak, tagliq va javonni ham arting — tuxumlar o‘simliksiz ham omon qoladi.',
        '- Yangi sotib olingan o‘simlikni diqqat bilan tekshiring va ikki hafta alohida saqlang. Deyarli har bir zararlanish yangi o‘simlik bilan keladi.'],
    ru:['Этих трёх сосущих вредителей лечат одинаково. Липкий налёт на листьях и мебели — их падь, и чаще всего замечают именно её.',
        '- Червец выглядит как белые ватные комочки в пазухах. Щитовка — коричневые бугорки на стеблях. Тля скапливается на молодых побегах.',
        '- Изолируйте растение: все трое распространяются быстро и легко переходят на соседей.',
        '- Точечно обработайте каждое насекомое ватной палочкой с 70% изопропиловым спиртом — он мгновенно растворяет восковой панцирь.',
        '- Затем опрыскайте всё растение инсектицидным мылом или разведённым маслом нима, захватив стебли, изнанку листьев и поверхность грунта.',
        '- Повторяйте еженедельно в течение месяца: личинки отрождаются постоянно, и одна обработка всегда оставляет выживших.',
        '- Протрите также горшок, поддон и полку — яйца выживают и вне растения.',
        '- Внимательно осматривайте новые покупки и держите их отдельно две недели. Почти всякое заражение приезжает с новым растением.'],
    zh:['这三种刺吸式害虫的处理方式相同。叶片和家具上的黏液是它们的蜜露，通常最先被发现的就是它。',
        '- 粉蚧像叶腋里的小团白棉絮；介壳虫是茎上褐色的小硬包；蚜虫则密集聚在新芽上。',
        '- 先隔离植株。这三种都传播很快，极易波及邻近植物。',
        '- 用棉签蘸 70% 异丙醇逐只点涂——能立刻溶解它们的蜡质外壳。',
        '- 然后用杀虫皂或稀释印楝油全株喷洒，覆盖茎干、叶背与土面。',
        '- 每周重复一次，持续一个月。若虫会不断孵化，只处理一次必有漏网之鱼。',
        '- 同时擦净花盆、托盘与搁板——虫卵离开植株也能存活。',
        '- 新买的植物要仔细检查并单独隔离两周。几乎所有虫害都是随新植物进门的。'],
    ar:['هذه الآفات الماصّة الثلاث تُعالَج بالطريقة نفسها. والبقايا اللزجة على الأوراق والأثاث هي ندوتها العسلية، وغالبًا ما تُلاحَظ أولًا.',
        '- البق الدقيقي يشبه خصلات قطن بيضاء صغيرة في آباط الأوراق، والحشرات القشرية نتوءات بنية على السيقان، والمنّ يتجمّع على النمو الجديد.',
        '- اعزل النبتة؛ فالثلاثة تنتشر بسرعة وتصل إلى الجيران بسهولة.',
        '- المس كل حشرة مباشرة بعود قطني مغموس في كحول أيزوبروبيل ٧٠٪ — فهو يذيب غلافها الشمعي فورًا.',
        '- ثم رُشّ النبتة كاملة بصابون مبيد أو زيت نيم مخفّف، مع تغطية السيقان وأسفل الأوراق وسطح التربة.',
        '- كرّر أسبوعيًا لمدة شهر؛ فالحوريات تفقس باستمرار، والمعالجة الواحدة تترك ناجين دائمًا.',
        '- امسح الأصيص والصحن والرف أيضًا — فالبيض يبقى حيًّا خارج النبتة.',
        '- افحص المشتريات الجديدة بعناية واعزلها أسبوعين؛ فمعظم الإصابات تصل مع نبتة جديدة.'] } });

P({ id:'root-rot', cat:'problem',
  kw:{ en:['root rot','rotting','black roots','mushy roots','mushy','soft at the base','soft base','going soft','brown at the base','stem soft','smell soil','dying plant','smells bad'],
       uz:['ildiz chiri','chirish','qora ildiz','yumshoq ildiz','tuproq hidi','olib ketyapti'],
       ru:['корнев','гнил','гние','чёрные корни','черные корни','мягкие корни','запах земли'],
       zh:['烂根','根腐','根发黑','根软','土有味','快死了'],
       ar:['تعفّن الجذور','عفن','جذور سوداء','جذور طرية','رائحة التربة'] },
  title:{ en:'Root rot — rescue procedure', uz:'Ildiz chirishi — qutqarish tartibi', ru:'Корневая гниль — как спасти растение', zh:'根腐——抢救流程', ar:'تعفّن الجذور — خطوات الإنقاذ' },
  body:{
    en:['Root rot is the most common killer of houseplants, and it is survivable if you act within a week of noticing it.',
        '- Confirm it: unpot the plant. Healthy roots are firm, pale and springy. Rotted roots are brown or black, slimy, and the outer layer slips off.',
        '- Wash all the old compost off the roots under lukewarm running water so you can see what you are working with.',
        '- Cut away every soft root with sterilised scissors. Be ruthless — leaving one rotted root reinfects the rest.',
        '- If you removed a lot of root, remove a similar proportion of leaves so the reduced root system can support the top.',
        '- Repot into a clean pot with fresh, barely damp, free-draining mix. Do not reuse the old soil, and wash the pot first.',
        '- Water sparingly for the first month and give bright indirect light. No fertiliser for six weeks.',
        '- If the stem base itself is soft and brown, the plant cannot be saved — but take a healthy top cutting and propagate it.'],
    uz:['Ildiz chirishi xonaki o‘simliklarni eng ko‘p nobud qiladi, lekin sezilgandan keyin bir hafta ichida harakat qilsangiz, qutqarish mumkin.',
        '- Tasdiqlang: o‘simlikni tuvakdan chiqaring. Sog‘lom ildiz qattiq, oqish va egiluvchan. Chirigan ildiz jigarrang yoki qora, shilimshiq va tashqi qavati sirg‘alib tushadi.',
        '- Nima bilan ishlayotganingizni ko‘rish uchun ildizdagi eski tuproqni iliq oqar suvda yuvib tashlang.',
        '- Har bir yumshoq ildizni zararsizlantirilgan qaychi bilan kesing. Shafqatsiz bo‘ling — bitta chirigan ildiz qolsa, qolganini qayta zararlaydi.',
        '- Ko‘p ildiz olib tashlangan bo‘lsa, shunga mos miqdorda bargni ham olib tashlang, toki kamaygan ildiz tizimi yuqori qismni ko‘tara olsin.',
        '- Toza tuvakka, yangi, biroz nam va suv o‘tkazadigan aralashmaga ko‘chiring. Eski tuproqni qayta ishlatmang, tuvakni avval yuving.',
        '- Birinchi oy kam sug‘oring va yorug‘, to‘g‘ridan tushmaydigan yorug‘lik bering. Olti hafta o‘g‘it bermang.',
        '- Agar poya tagi ham yumshoq va jigarrang bo‘lsa, o‘simlikni qutqarib bo‘lmaydi — lekin sog‘lom uchidan qalamcha olib ko‘paytiring.'],
    ru:['Корневая гниль — главная причина гибели комнатных растений, но её можно пережить, если начать действовать в течение недели.',
        '- Подтвердите диагноз: выньте растение. Здоровые корни плотные, светлые, упругие. Гнилые — бурые или чёрные, склизкие, внешний слой сползает.',
        '- Смойте весь старый грунт с корней тёплой проточной водой, чтобы видеть реальную картину.',
        '- Срежьте стерильными ножницами все мягкие корни. Будьте безжалостны — один оставленный гнилой корень заразит остальные.',
        '- Если удалено много корней, удалите сопоставимую долю листьев, чтобы уменьшенная корневая система справилась с кроной.',
        '- Пересадите в чистый горшок со свежим, едва влажным водопроницаемым субстратом. Старый грунт не используйте, горшок вымойте.',
        '- Первый месяц поливайте скупо и обеспечьте яркий рассеянный свет. Удобрения — не раньше чем через шесть недель.',
        '- Если основание стебля тоже мягкое и бурое, растение не спасти — но срежьте здоровую верхушку и укорените её.'],
    zh:['根腐是室内植物最常见的死因，但只要在发现后一周内处理，通常救得回来。',
        '- 先确认：脱盆检查。健康的根结实、浅色、有弹性；烂根呈褐色或黑色、黏滑，外皮一捋就脱。',
        '- 用温水冲净根上所有旧土，这样才能看清实际情况。',
        '- 用消毒剪刀剪掉每一条发软的根。要果断——留下一条烂根就会重新感染其余部分。',
        '- 如果剪掉了大量根系，也要相应摘掉同比例的叶片，让缩小的根系撑得住上部。',
        '- 换入干净的盆与全新、略微湿润、排水良好的基质。旧土不要再用，旧盆必须先洗净。',
        '- 第一个月少量浇水，给予明亮散射光。六周内不要施肥。',
        '- 如果茎基部本身也已发软变褐，这株就救不回来了——但可以剪取健康的顶梢扦插繁殖。'],
    ar:['تعفّن الجذور هو أكثر ما يقتل النباتات المنزلية، ويمكن النجاة منه إذا تصرّفت خلال أسبوع من ملاحظته.',
        '- تأكّد أولًا: أخرج النبتة من الأصيص. الجذور السليمة متماسكة فاتحة مرنة، والمتعفّنة بنية أو سوداء لزجة وتنزلق قشرتها الخارجية.',
        '- اغسل كل التربة القديمة عن الجذور بماء فاتر جارٍ حتى ترى ما تتعامل معه بوضوح.',
        '- اقطع كل جذر طري بمقص معقّم. كن حازمًا — فترك جذر متعفّن واحد يعيد إصابة البقية.',
        '- إذا أزلت قدرًا كبيرًا من الجذور، أزِل نسبة مماثلة من الأوراق كي يتمكّن الجذر المتبقي من إعالة الجزء العلوي.',
        '- انقلها إلى أصيص نظيف بخليط جديد رطب قليلًا وجيّد الصرف. ولا تعِد استخدام التربة القديمة، واغسل الأصيص أولًا.',
        '- اسقِ باعتدال شديد في الشهر الأول مع ضوء ساطع غير مباشر، ولا سماد لمدة ستة أسابيع.',
        '- وإذا كانت قاعدة الساق نفسها طرية بنية فلا يمكن إنقاذ النبتة — لكن خذ عقلة علوية سليمة وأكثرها.'] } });

P({ id:'humidity', cat:'environment',
  kw:{ en:['humidity','humid','dry air','mist','misting','humidifier','pebble tray'],
       uz:['namlik','quruq havo','purkash','namlagich','nam havo'],
       ru:['влажность','сухой воздух','опрыскив','увлажнитель','поддон с галькой'],
       zh:['湿度','空气干','喷雾','加湿器','湿润'],
       ar:['رطوبة','هواء جاف','رذاذ','مرطّب','صينية حصى'] },
  title:{ en:'Raising humidity properly', uz:'Namlikni to‘g‘ri oshirish', ru:'Как правильно поднять влажность', zh:'正确提高湿度', ar:'رفع الرطوبة بالشكل الصحيح' },
  body:{
    en:['Tropical plants evolved at 70–90% humidity. A heated room in winter can fall to 25%, which is drier than most deserts.',
        '- Misting raises humidity for about ten minutes and does almost nothing long term. It can also spread fungal spots on fuzzy leaves.',
        '- Grouping plants together genuinely works — they humidify each other through transpiration.',
        '- A pebble tray (a saucer of gravel with water below the pot base) raises local humidity by 10–15%.',
        '- A small ultrasonic humidifier is the only reliable fix, and the cheapest solution for a whole shelf of tropicals.',
        '- Bathrooms and kitchens with a window are naturally humid — ideal for ferns, calatheas and orchids.',
        '- A cheap hygrometer removes all the guesswork. Aim for 50% minimum, 60% for calatheas and ferns.'],
    uz:['Tropik o‘simliklar 70–90% namlikda shakllangan. Qishda isitiladigan xona 25% gacha tushishi mumkin — bu ko‘pchilik cho‘llardan ham quruqroq.',
        '- Purkash namlikni taxminan o‘n daqiqaga oshiradi va uzoq muddatda deyarli hech narsa bermaydi. Tukli barglarda zamburug‘ dog‘larini ham tarqatishi mumkin.',
        '- O‘simliklarni birga joylashtirish haqiqatan ishlaydi — ular transpiratsiya orqali bir-birini namlaydi.',
        '- Shag‘alli tovoq (tuvak tagiga tegmaydigan suv solingan shag‘al) mahalliy namlikni 10–15% ga oshiradi.',
        '- Kichik ultratovushli namlagich — yagona ishonchli yechim va butun bir javon tropik o‘simlik uchun eng arzon variant.',
        '- Derazasi bor hammom va oshxona tabiiy ravishda nam — paportnik, kalateya va orxideya uchun ideal.',
        '- Arzon gigrometr barcha taxminlarni yo‘qotadi. Kamida 50%, kalateya va paportnik uchun 60% ga intiling.'],
    ru:['Тропические растения сформировались при влажности 70–90%. Зимой в отапливаемой комнате она падает до 25% — суше, чем в большинстве пустынь.',
        '- Опрыскивание поднимает влажность минут на десять и в долгой перспективе почти бесполезно. На опушённых листьях оно ещё и разносит грибковые пятна.',
        '- Группировка растений действительно работает — они увлажняют друг друга за счёт транспирации.',
        '- Поддон с галькой (вода ниже дна горшка) поднимает локальную влажность на 10–15%.',
        '- Небольшой ультразвуковой увлажнитель — единственное надёжное решение и самое дешёвое для целой полки тропиканок.',
        '- Ванная и кухня с окном влажные от природы — идеальны для папоротников, калатей и орхидей.',
        '- Недорогой гигрометр снимает все вопросы. Цель — минимум 50%, для калатей и папоротников 60%.'],
    zh:['热带植物在 70–90% 的湿度中演化而来。冬天供暖的房间可能低至 25%，比多数沙漠还干。',
        '- 喷雾只能让湿度维持约十分钟，长期几乎无效；在有绒毛的叶片上还可能传播真菌斑点。',
        '- 把植物摆在一起确实有用——它们通过蒸腾相互加湿。',
        '- 湿卵石托盘（水面低于盆底的石子盘）可把局部湿度提高 10–15%。',
        '- 小型超声波加湿器是唯一可靠的办法，对一整架热带植物来说也最划算。',
        '- 带窗户的浴室和厨房天然湿润——非常适合蕨类、竹芋与兰花。',
        '- 一个便宜的湿度计就能省去所有猜测。目标至少 50%，竹芋与蕨类则要 60%。'],
    ar:['تطوّرت النباتات الاستوائية عند رطوبة ٧٠–٩٠٪. وقد تهبط الغرفة المدفّأة شتاءً إلى ٢٥٪، أي أجفّ من معظم الصحاري.',
        '- الرذاذ يرفع الرطوبة نحو عشر دقائق فقط ولا يفيد على المدى الطويل، وقد ينشر البقع الفطرية على الأوراق الوبرية.',
        '- تجميع النباتات معًا مفيد فعلًا — فهي ترطّب بعضها عبر النتح.',
        '- صينية الحصى (حصى وماء تحت قاعدة الأصيص) ترفع الرطوبة المحيطة بنسبة ١٠–١٥٪.',
        '- المرطّب فوق الصوتي الصغير هو الحل الموثوق الوحيد، والأرخص لرفّ كامل من النباتات الاستوائية.',
        '- الحمّامات والمطابخ ذات النوافذ رطبة بطبيعتها — مثالية للسرخسيات والكالاثيا والأوركيد.',
        '- مقياس رطوبة رخيص يُنهي كل التخمين. استهدف ٥٠٪ كحد أدنى، و٦٠٪ للكالاثيا والسرخسيات.'] } });

P({ id:'toxicity', cat:'safety',
  kw:{ en:['toxic','poison','poisonous','safe for cats','safe for dogs','pet safe','child safe','ate a leaf','animal','cat','cats','dog','dogs','pet','pets','kitten','puppy','baby','toddler'],
       uz:['zaharli','zahar','mushuk','it uchun','bola','xavfsiz','barg yedi','hayvon','uy hayvoni'],
       ru:['ядовит','токсич','опасно','кошк','кот','соба','детей','ребен','съел лист','питомц','животн'],
       zh:['有毒','对猫','对狗','宠物安全','孩子','误食','安全吗'],
       ar:['سام','سمي','للقطط','للكلاب','للأطفال','امن','اكل ورقه','حيوان اليف','ضار'] },
  title:{ en:'Plants, pets and children', uz:'O‘simliklar, uy hayvonlari va bolalar', ru:'Растения, питомцы и дети', zh:'植物、宠物与孩子', ar:'النباتات والحيوانات الأليفة والأطفال' },
  body:{
    en:['Most common houseplant poisonings are mild, but a few species deserve real caution in a home with pets or toddlers.',
        '- The main culprits are aroids — monstera, pothos, philodendron, peace lily, ZZ and anthurium. They contain calcium oxalate crystals that cause intense mouth burning and drooling, rarely anything worse.',
        '- Ficus species (rubber plant, fiddle leaf) have an irritant milky sap that affects mouth and skin.',
        '- Genuinely dangerous and worth avoiding entirely with cats: lilies (Lilium and Hemerocallis), sago palm, oleander and dieffenbachia.',
        '- Reliably pet-safe choices: Boston fern, maidenhair fern, calathea, areca and kentia palms, African violet, string of hearts, echeveria, basil and rosemary.',
        '- If an animal chews a leaf, rinse its mouth with water, offer something to eat, and watch it. Call a vet if there is persistent vomiting, drooling or difficulty swallowing.',
        '- Practical defence: hang trailing plants, use high shelves, and give cats their own pot of cat grass to chew instead.'],
    uz:['Xonaki o‘simliklardan zaharlanishning aksariyati yengil kechadi, lekin bir nechta tur uy hayvoni yoki kichik bola bor uyda jiddiy ehtiyotni talab qiladi.',
        '- Asosiy xavf — aroidlar: monstera, stsindapsus, filodendron, spatifillum, zamiokulkas va anturium. Ulardagi kalsiy oksalat kristallari og‘izda kuchli achishish va so‘lak oqishiga sabab bo‘ladi, kamdan-kam og‘irroq.',
        '- Fikus turlari (kauchuk fikusi, skripkabargli) og‘iz va teriga ta’sir qiladigan sutsimon shiraga ega.',
        '- Haqiqatan xavfli va mushuk bor uyda umuman saqlamaslik kerak: liliya (Lilium va Hemerocallis), sago palmasi, oleandr va diffenbaxiya.',
        '- Ishonchli xavfsiz tanlovlar: Boston va adiantum paportniklari, kalateya, areka va kentiya palmalari, Afrika binafshasi, yuraklar shodasi, exeveriya, rayhon va rozmarin.',
        '- Hayvon bargni chaynasa, og‘zini suv bilan chayib, yegulik bering va kuzating. Qusish, so‘lak oqishi yoki yutinish qiyinlashsa veterinarga murojaat qiling.',
        '- Amaliy himoya: osma o‘simliklarni ilib qo‘ying, baland javonlardan foydalaning va mushukka chaynash uchun alohida mushuk o‘ti tuvagini bering.'],
    ru:['Большинство отравлений комнатными растениями протекают легко, но несколько видов требуют настоящей осторожности в доме с питомцами или малышами.',
        '- Главные виновники — ароидные: монстера, эпипремнум, филодендрон, спатифиллум, замиокулькас и антуриум. Кристаллы оксалата кальция вызывают сильное жжение во рту и слюнотечение, реже что-то серьёзнее.',
        '- У фикусов (каучуконосный, лировидный) млечный сок раздражает рот и кожу.',
        '- По-настоящему опасны и несовместимы с кошками: лилии (Lilium и Hemerocallis), саговая пальма, олеандр и диффенбахия.',
        '- Надёжно безопасные варианты: нефролепис, адиантум, калатея, арека и кентия, сенполия, церопегия, эхеверия, базилик и розмарин.',
        '- Если животное пожевало лист, прополощите ему пасть водой, предложите еду и наблюдайте. При непрекращающейся рвоте, слюнотечении или трудном глотании — к ветеринару.',
        '- Практическая защита: подвесные кашпо, высокие полки и отдельный горшок кошачьей травы, которую можно грызть.'],
    zh:['大多数室内植物中毒都比较轻微，但在有宠物或幼儿的家中，有几类植物确实需要当心。',
        '- 主要风险来自天南星科：龟背竹、绿萝、蔓绿绒、白鹤芋、金钱树与红掌。它们含草酸钙针晶，会引起口腔剧烈灼痛和流涎，极少更严重。',
        '- 榕属植物（橡皮树、琴叶榕）的乳白色汁液会刺激口腔与皮肤。',
        '- 真正危险、养猫家庭应完全避免的是：百合（Lilium 与萱草属）、苏铁、夹竹桃与花叶万年青。',
        '- 确实安全的选择：波士顿蕨、铁线蕨、竹芋、散尾葵与荷威椰子、非洲堇、爱之蔓、石莲花、罗勒与迷迭香。',
        '- 若宠物啃了叶子，用清水冲洗其口腔，喂点食物并观察。若持续呕吐、流涎或吞咽困难，请立即就医。',
        '- 实用防护：把垂吊植物挂高、使用高处搁板，并单独给猫准备一盆猫草供它啃咬。'],
    ar:['معظم حالات التسمّم بالنباتات المنزلية خفيفة، لكن بعض الأنواع تستحق حذرًا حقيقيًا في بيت فيه حيوانات أليفة أو أطفال صغار.',
        '- المسبّب الرئيسي هو القلقاسيات: مونستيرا، بوتس، فيلودندرون، زنبق السلام، زاميوكولكاس وأنثوريوم. تحتوي بلورات أكسالات الكالسيوم التي تسبّب حرقة شديدة في الفم وسيلان لعاب، ونادرًا ما تتجاوز ذلك.',
        '- أنواع الفيكس (نبات المطاط، تين الكمان) فيها عصارة لبنية مهيّجة للفم والجلد.',
        '- خطير فعلًا ويجب تجنّبه تمامًا مع القطط: الزنابق (Lilium و Hemerocallis)، نخيل الساغو، الدفلة، والديفنباخيا.',
        '- خيارات آمنة بثقة: سرخس بوسطن وشعر البنات، الكالاثيا، نخيل الأريكا والكنتيا، البنفسج الأفريقي، سلسلة القلوب، الإتشيفيريا، الريحان وإكليل الجبل.',
        '- إذا مضغ حيوانك ورقة، اشطف فمه بالماء وقدّم له طعامًا وراقبه. واتصل بالطبيب البيطري عند استمرار القيء أو سيلان اللعاب أو صعوبة البلع.',
        '- الحماية العملية: علّق النباتات المتدلّية، واستخدم رفوفًا مرتفعة، وخصّص للقط أصيصًا من عشب القطط ليمضغه بدلًا منها.'] } });

P({ id:'leaf-drop', cat:'problem',
  kw:{ en:['dropping leaves','leaf drop','losing leaves','falling leaves','shedding','shock','moved'],
       uz:['barg tokish','barg to‘kish','barglar tushyapti','to‘kilyapti','stress','kochirdim'],
       ru:['сбрасывает листья','опадают','листопад','теряет листья','стресс','переставил'],
       zh:['掉叶','落叶','叶子掉','掉光','应激','搬动'],
       ar:['تساقط الأوراق','يفقد أوراقه','سقوط الورق','صدمة','نقلت'] },
  title:{ en:'Sudden leaf drop', uz:'To‘satdan barg to‘kilishi', ru:'Внезапный листопад', zh:'突然大量掉叶', ar:'تساقط الأوراق المفاجئ' },
  body:{
    en:['Dropping leaves is a stress response, not a disease. Figs, especially the fiddle leaf, do it at the slightest provocation.',
        '- The usual trigger is change: a new home, a new room, a different light level, or a cold draught from a door or window.',
        '- A plant delivered this week will often drop a few leaves. That is normal acclimatisation and stops within three weeks.',
        '- Check for cold first. Below about 12°C most tropical plants shed leaves rapidly; so does a radiator blowing hot dry air on them.',
        '- Then check watering. Both extremes cause leaf drop, so feel the soil before assuming it is thirsty.',
        '- The most useful thing you can do is nothing. Pick one good spot, settle on a watering routine and leave the plant alone.',
        '- Do not repot, feed or move a plant that is already dropping leaves — each of those adds another stress.'],
    uz:['Barg to‘kilishi — kasallik emas, stressga javob. Fikuslar, ayniqsa skripkabargli, eng kichik bahonada ham shunday qiladi.',
        '- Odatiy sabab — o‘zgarish: yangi uy, boshqa xona, yorug‘lik darajasining o‘zgarishi yoki eshik va derazadan kelayotgan sovuq shamol.',
        '- Shu hafta yetkazilgan o‘simlik ko‘pincha bir necha bargini to‘kadi. Bu normal moslashuv va uch hafta ichida to‘xtaydi.',
        '- Avvalo sovuqni tekshiring. Taxminan 12°C dan past haroratda ko‘pchilik tropik o‘simlik tez barg to‘kadi; issiq quruq havo puflayotgan radiator ham shunday ta’sir qiladi.',
        '- So‘ng sug‘orishni tekshiring. Ikkala chekka ham barg to‘kilishiga olib keladi, shuning uchun tashna deb o‘ylashdan oldin tuproqni paypaslab ko‘ring.',
        '- Eng foydali ish — hech narsa qilmaslik. Bitta yaxshi joy tanlang, sug‘orish tartibini belgilang va o‘simlikni tinch qo‘ying.',
        '- Barg to‘kayotgan o‘simlikni ko‘chirmang, o‘g‘itlamang va joyini o‘zgartirmang — bularning har biri yana bir stress qo‘shadi.'],
    ru:['Сброс листьев — это реакция на стресс, а не болезнь. Фикусы, особенно лировидный, делают это при малейшем поводе.',
        '- Обычный триггер — перемена: новый дом, другая комната, другой уровень света или холодный сквозняк от двери и окна.',
        '- Растение, привезённое на этой неделе, часто сбрасывает несколько листьев. Это нормальная акклиматизация, она заканчивается за три недели.',
        '- Сначала проверьте холод. Ниже примерно 12°C большинство тропических растений быстро теряют листья; то же делает батарея, дующая сухим горячим воздухом.',
        '- Затем проверьте полив. К листопаду приводят обе крайности, поэтому пощупайте грунт, прежде чем решить, что растение хочет пить.',
        '- Самое полезное, что можно сделать, — ничего. Выберите одно хорошее место, определитесь с режимом полива и оставьте растение в покое.',
        '- Не пересаживайте, не подкармливайте и не переставляйте растение, которое уже сбрасывает листья, — каждое из этих действий добавляет новый стресс.'],
    zh:['掉叶是应激反应，而不是病害。榕属植物、尤其是琴叶榕，稍有风吹草动就会掉叶。',
        '- 常见诱因就是「变化」：换了家、换了房间、光照水平改变，或门窗吹来的冷风。',
        '- 本周刚送到的植株往往会掉几片叶，这是正常的适应过程，三周内会停止。',
        '- 先排查低温。低于约 12°C 时多数热带植物会迅速落叶；暖气直吹的干热风同样如此。',
        '- 再检查浇水。过干过湿都会导致掉叶，所以在断定「缺水」之前请先摸土。',
        '- 此时最有用的做法是——什么都别做。选定一个好位置，固定浇水节奏，然后让它安静待着。',
        '- 正在掉叶的植株不要换盆、不要施肥、不要再挪动，这些都只会叠加新的压力。'],
    ar:['تساقط الأوراق استجابة للإجهاد وليس مرضًا. وأشجار التين، وخاصة تين الكمان، تفعل ذلك لأتفه سبب.',
        '- المحفّز المعتاد هو التغيير: بيت جديد، غرفة مختلفة، مستوى إضاءة مغاير، أو تيار هواء بارد من باب أو نافذة.',
        '- النبتة التي وصلت هذا الأسبوع غالبًا ما تُسقط بعض الأوراق. هذا تأقلم طبيعي ويتوقّف خلال ثلاثة أسابيع.',
        '- افحص البرودة أولًا. تحت ١٢ درجة مئوية تقريبًا تُسقط معظم النباتات الاستوائية أوراقها بسرعة، وكذلك يفعل مشعّ حراري ينفخ هواءً جافًا ساخنًا عليها.',
        '- ثم افحص الري. كلا الطرفين يسبّب التساقط، فتحسّس التربة قبل أن تفترض أنها عطشى.',
        '- أنفع ما يمكنك فعله هو ألّا تفعل شيئًا. اختر مكانًا جيدًا واحدًا، وثبّت روتين الري، واترك النبتة وشأنها.',
        '- لا تنقل نبتة تُسقط أوراقها ولا تسمّدها ولا تغيّر أصيصها — فكل من ذلك يضيف إجهادًا جديدًا.'] } });

P({ id:'drooping', cat:'problem',
  kw:{ en:['droop','drooping','wilting','limp','sad','floppy','falling over'],
       uz:['solgan','so‘lgan','egilib','osilib','bo‘shashgan','yiqilib'],
       ru:['поник','вянет','увял','обвис','опустил листья','падает'],
       zh:['耷拉','萎蔫','垂','蔫了','软趴趴','倒伏'],
       ar:['ذابل','متهدّل','ذبول','مرتخٍ','يسقط'] },
  title:{ en:'Drooping and wilting', uz:'So‘lish va egilib qolish', ru:'Поникание и увядание', zh:'萎蔫与耷拉', ar:'الذبول والتهدّل' },
  body:{
    en:['A drooping plant is asking for water, drowning in it, or too cold. The soil tells you which, so check before you act.',
        '- Soil dry and pot light: it is thirsty. Soak it from below and it will usually recover within four hours.',
        '- Soil wet and leaves limp: the roots are suffocating and cannot take water up. Stop watering and check for rot.',
        '- Both soil and temperature fine: look for a cold draught, a recent move, or direct midday sun scorching the leaves.',
        '- Peace lilies droop dramatically and recover completely within hours — many owners use this as a watering signal, though it does stress the plant.',
        '- A plant that droops only in the afternoon heat and recovers overnight is fine; it is simply transpiring faster than its roots can supply.',
        '- Drooping after repotting is normal for a week while damaged root hairs regrow. Keep it shaded and lightly moist.'],
    uz:['So‘lgan o‘simlik yo suv so‘rayapti, yo suvda bo‘g‘ilyapti, yoki sovqotgan. Qaysi biri ekanini tuproq aytadi — harakat qilishdan oldin tekshiring.',
        '- Tuproq quruq, tuvak yengil: u tashna. Pastdan cho‘ktiring, odatda to‘rt soat ichida tiklanadi.',
        '- Tuproq nam, barglar bo‘shashgan: ildiz bo‘g‘ilgan va suvni ko‘tara olmayapti. Sug‘orishni to‘xtating va chirishni tekshiring.',
        '- Tuproq ham, harorat ham joyida: sovuq shamol, yaqinda ko‘chirilgani yoki tush paytidagi to‘g‘ridan quyosh kuydirgani-yo‘qligini qarang.',
        '- Spatifillum keskin so‘liydi va bir necha soatda to‘liq tiklanadi — ko‘pchilik buni sug‘orish signali sifatida ishlatadi, garchi bu o‘simlikni charchatsa ham.',
        '- Faqat tushdan keyingi issiqda so‘lib, kechasi tiklanadigan o‘simlik sog‘lom; u shunchaki ildiz yetkazib berolganidan tezroq bug‘latyapti.',
        '- Ko‘chirishdan keyin bir hafta so‘lish normal — shikastlangan ildiz tuklari tiklanmoqda. Soyada saqlang va yengil nam qiling.'],
    ru:['Поникшее растение либо просит воды, либо тонет в ней, либо замёрзло. Какое именно — скажет грунт, поэтому сначала проверьте.',
        '- Грунт сухой, горшок лёгкий: растение хочет пить. Замочите снизу — обычно оно оживает за четыре часа.',
        '- Грунт мокрый, листья вялые: корни задыхаются и не могут поднимать воду. Прекратите полив и проверьте на гниль.',
        '- И грунт, и температура в норме: ищите сквозняк, недавний переезд или прямое полуденное солнце, обжигающее листья.',
        '- Спатифиллум поникает очень картинно и полностью восстанавливается за часы — многие используют это как сигнал к поливу, хотя для растения это стресс.',
        '- Растение, которое вянет только в послеобеденную жару и восстанавливается за ночь, здорово: оно просто испаряет быстрее, чем корни успевают подавать.',
        '- Поникание в течение недели после пересадки нормально, пока отрастают повреждённые корневые волоски. Держите в тени и слегка влажным.'],
    zh:['耷拉的植株要么渴了，要么被水淹了，要么太冷。到底是哪一种，土会告诉你——动手前先检查。',
        '- 土干、盆轻：就是缺水。浸盆补水，通常四小时内恢复。',
        '- 土湿、叶却发软：根在缺氧，吸不上水。立即停水并检查是否烂根。',
        '- 土和温度都正常：那就找冷风、近期挪动，或正午直射日灼。',
        '- 白鹤芋会「戏剧性」地垂下，几小时内就完全恢复——不少人把它当作浇水信号，不过这确实会让植株受累。',
        '- 只在午后高温时萎蔫、夜里自行恢复的植株是健康的：它只是蒸腾速度快过根系供水。',
        '- 换盆后一周内发蔫属正常，受损的根毛正在重新长出。请放在阴凉处并保持微湿。'],
    ar:['النبتة المتهدّلة إمّا تطلب الماء، أو تغرق فيه، أو تشعر بالبرد. والتربة تخبرك بأيّها، فافحص قبل أن تتصرّف.',
        '- تربة جافة وأصيص خفيف: إنها عطشى. انقعها من الأسفل وستتعافى عادةً خلال أربع ساعات.',
        '- تربة رطبة وأوراق مرتخية: الجذور تختنق ولا تستطيع رفع الماء. أوقف الري وافحص التعفّن.',
        '- التربة والحرارة كلتاهما جيدتان: ابحث عن تيار هواء بارد، أو نقل حديث، أو شمس ظهيرة مباشرة تحرق الأوراق.',
        '- زنبق السلام يتهدّل بشكل درامي ثم يتعافى تمامًا خلال ساعات — ويستخدمه كثيرون كإشارة للري، رغم أن ذلك يُجهد النبتة.',
        '- النبتة التي تذبل في حرّ العصر فقط وتتعافى ليلًا سليمة؛ فهي ببساطة تنتح أسرع مما تستطيع جذورها التعويض.',
        '- التهدّل بعد تغيير الأصيص طبيعي لأسبوع ريثما تنمو الشعيرات الجذرية التالفة. أبقِها في الظل ورطبة قليلًا.'] } });

P({ id:'mold', cat:'problem',
  kw:{ en:['mould','mold','white fuzz on soil','fungus on soil','white crust','powdery mildew','algae'],
       uz:['mogor','mog‘or','tuproqda oq','oq qatlam','zamburug‘','yashil qoplama'],
       ru:['плесень','белый налёт на земле','грибок на почве','белая корка','мучнистая роса'],
       zh:['霉','土表发白','白毛','白色结壳','白粉病','青苔'],
       ar:['عفن','طبقة بيضاء','فطر على التربة','قشرة بيضاء','البياض الدقيقي'] },
  title:{ en:'White mould and crust on the soil', uz:'Tuproqdagi oq mog‘or va qatlam', ru:'Белая плесень и налёт на грунте', zh:'土面白霉与白色结壳', ar:'العفن الأبيض والقشرة على التربة' },
  body:{
    en:['Two different white things appear on potting soil, and they need opposite responses.',
        '- Fluffy white mould is a harmless saprophytic fungus living on organic matter. It harms nothing, but it tells you the surface is too wet and the air too still.',
        '- Scrape it off, let the top layer dry fully, and improve airflow with an open window or a small fan. A thin sand topping prevents its return.',
        '- Hard white or yellow crust is mineral salts from hard water and fertiliser. It can burn roots and block drainage.',
        '- Remove the crust and flush the pot: run lukewarm water through it for a full minute, let it drain, and repeat monthly.',
        '- Powdery mildew is different again — a white dust on the leaves themselves. Improve airflow, remove affected leaves and spray a 1:9 milk-to-water solution or a proper fungicide.',
        '- Green film on the soil or pot is algae. Harmless, caused by light plus constant moisture; scrape off and water less often.'],
    uz:['Tuvak tuprog‘ida ikki xil oq narsa paydo bo‘ladi va ular qarama-qarshi choralarni talab qiladi.',
        '- Momiqsimon oq mog‘or — organik moddada yashaydigan zararsiz saprofit zamburug‘. U hech narsaga zarar qilmaydi, lekin yuza juda nam va havo turg‘un ekanini bildiradi.',
        '- Uni qirib tashlang, yuqori qatlamni to‘liq quriting va deraza yoki kichik ventilyator bilan havo almashinuvini yaxshilang. Yupqa qum qatlami qaytishiga yo‘l qo‘ymaydi.',
        '- Qattiq oq yoki sariq qatlam — qattiq suv va o‘g‘itdan qolgan mineral tuzlar. U ildizni kuydirishi va drenajni berkitishi mumkin.',
        '- Qatlamni olib tashlang va tuvakni yuving: to‘liq bir daqiqa iliq suv o‘tkazing, oqib ketishini kuting va har oy takrorlang.',
        '- Un-shudring esa boshqa narsa — barglarning o‘zidagi oq chang. Havo almashinuvini yaxshilang, zararlangan barglarni olib tashlang va 1:9 sut-suv eritmasi yoki fungitsid purkang.',
        '- Tuproq yoki tuvakdagi yashil parda — suvo‘t. Zararsiz, yorug‘lik va doimiy namlikdan paydo bo‘ladi; qirib tashlang va kamroq sug‘oring.'],
    ru:['На грунте появляются два разных белых налёта, и реагировать на них нужно противоположным образом.',
        '- Пушистая белая плесень — безобидный сапрофитный гриб, живущий на органике. Он ничему не вредит, но говорит, что поверхность слишком сырая, а воздух застойный.',
        '- Соскоблите её, дайте верхнему слою полностью просохнуть и наладьте проветривание — форточка или маленький вентилятор. Тонкий слой песка предотвратит возвращение.',
        '- Твёрдая белая или жёлтая корка — минеральные соли от жёсткой воды и удобрений. Она может обжигать корни и мешать дренажу.',
        '- Снимите корку и промойте горшок: лейте тёплую воду целую минуту, дайте стечь и повторяйте ежемесячно.',
        '- Мучнистая роса — это другое: белая пыль на самих листьях. Улучшите проветривание, удалите поражённые листья и опрыскайте раствором молока с водой 1:9 или фунгицидом.',
        '- Зелёная плёнка на грунте или горшке — водоросли. Безвредны, появляются от света и постоянной сырости; соскоблите и поливайте реже.'],
    zh:['盆土表面会出现两种不同的白色物质，处理方式恰好相反。',
        '- 蓬松的白霉是以有机质为生的腐生真菌，本身无害，但它说明表土太湿、空气不流通。',
        '- 刮掉它，让表层彻底干透，并开窗或用小风扇改善通风。铺一层薄沙可防止再生。',
        '- 坚硬的白色或黄色结壳是硬水与肥料留下的矿物盐，会灼伤根系并堵塞排水。',
        '- 清除结壳并冲盆：用温水持续冲洗整整一分钟，沥干，之后每月重复一次。',
        '- 白粉病又是另一回事——出现在叶片本身的白色粉末。请改善通风、摘除病叶，并喷洒 1:9 的牛奶水溶液或正规杀菌剂。',
        '- 土面或盆壁的绿色薄膜是藻类，无害，由光照加持续潮湿造成；刮掉并减少浇水频率即可。'],
    ar:['يظهر على تربة الأصص نوعان مختلفان من البياض، ويحتاج كل منهما استجابة معاكسة للآخر.',
        '- العفن الأبيض الوبري فطر رمّي غير ضار يعيش على المادة العضوية. لا يؤذي شيئًا، لكنه يخبرك أن السطح شديد الرطوبة والهواء راكد.',
        '- اكشطه، ودع الطبقة العليا تجفّ تمامًا، وحسّن التهوية بنافذة مفتوحة أو مروحة صغيرة. وطبقة رمل رقيقة تمنع عودته.',
        '- أما القشرة البيضاء أو الصفراء الصلبة فهي أملاح معدنية من الماء العسر والأسمدة، وقد تحرق الجذور وتسدّ الصرف.',
        '- أزِل القشرة واغسل الأصيص: مرّر ماءً فاترًا خلاله دقيقة كاملة، واتركه يصرف، وكرّر ذلك شهريًا.',
        '- البياض الدقيقي شيء آخر تمامًا — غبار أبيض على الأوراق نفسها. حسّن التهوية، وأزِل الأوراق المصابة، ورُشّ محلول حليب وماء ١:٩ أو مبيدًا فطريًا مناسبًا.',
        '- الغشاء الأخضر على التربة أو الأصيص طحالب غير ضارة سببها الضوء مع الرطوبة الدائمة؛ اكشطه واسقِ بوتيرة أقل.'] } });

P({ id:'bloom', cat:'flowering',
  kw:{ en:['flower','bloom','blooming','not flowering','rebloom','buds','wont flower','blossom'],
       uz:['gul','gullash','gullamayapti','kurtak','qayta gullash'],
       ru:['цвет','цветение','не цветёт','бутоны','зацвести','повторное цветение'],
       zh:['开花','不开花','花苞','复花','花期'],
       ar:['إزهار','يزهر','لا يزهر','براعم','تكرار الإزهار'] },
  title:{ en:'Getting a plant to flower', uz:'O‘simlikni gullatish', ru:'Как заставить растение зацвести', zh:'让植物开花', ar:'جعل النبتة تُزهر' },
  body:{
    en:['A plant that grows beautiful leaves but refuses to flower is nearly always getting too little light or too much nitrogen.',
        '- Flowering costs far more energy than leaves. Almost every flowering houseplant needs bright light to afford it.',
        '- Switch from a balanced feed to a high-potassium one (tomato feed works perfectly) during the growing season.',
        '- Stop nitrogen-heavy feeding, which pushes lush foliage at the direct expense of buds.',
        '- Many species need a trigger: orchids rebloom after two weeks of nights about 10°C cooler than their days. Put a phalaenopsis near a cool window in autumn.',
        '- Being slightly root-bound encourages flowering in orchids, peace lilies and African violets — do not rush to repot them.',
        '- Deadhead spent flowers promptly so the plant invests in new buds instead of seed.',
        '- Be patient. Many plants simply need to reach a certain maturity before flowering is possible at all.'],
    uz:['Chiroyli barg chiqarib, gullashdan bosh tortayotgan o‘simlik deyarli har doim yorug‘lik yetishmasligi yoki ortiqcha azotdan aziyat chekadi.',
        '- Gullash bargdan ko‘ra ancha ko‘p energiya talab qiladi. Deyarli har bir gulli xonaki o‘simlikka buning uchun yorqin yorug‘lik kerak.',
        '- O‘sish davrida muvozanatli o‘g‘itdan kaliyga boy o‘g‘itga o‘ting (pomidor uchun o‘g‘it juda mos keladi).',
        '- Azotga boy o‘g‘itlashni to‘xtating: u kurtaklar hisobiga quyuq bargni kuchaytiradi.',
        '- Ko‘p turga turtki kerak: orxideyalar kechalari kunduzdan 10°C sovuqroq bo‘lgan ikki haftadan keyin qayta gullaydi. Kuzda falenopsisni salqin deraza yoniga qo‘ying.',
        '- Ildizning biroz siqilib turishi orxideya, spatifillum va Afrika binafshasida gullashni rag‘batlantiradi — ularni shoshib ko‘chirmang.',
        '- So‘lgan gullarni darhol olib tashlang, shunda o‘simlik urug‘ emas, yangi kurtaklarga kuch sarflaydi.',
        '- Sabr qiling. Ko‘p o‘simlik gullashi uchun avvalo ma’lum yetuklikka yetishi kerak.'],
    ru:['Растение с красивыми листьями, которое не цветёт, почти всегда получает слишком мало света или слишком много азота.',
        '- Цветение стоит гораздо больше энергии, чем листья. Почти всем цветущим комнатным нужен яркий свет, чтобы его себе позволить.',
        '- В период роста перейдите со сбалансированного удобрения на калийное (удобрение для томатов подходит идеально).',
        '- Прекратите азотные подкормки: они гонят пышную листву прямо в ущерб бутонам.',
        '- Многим видам нужен триггер: орхидеи зацветают после двух недель с ночами примерно на 10°C холоднее дня. Осенью поставьте фаленопсис к прохладному окну.',
        '- Небольшая теснота в горшке стимулирует цветение у орхидей, спатифиллума и сенполий — не спешите их пересаживать.',
        '- Своевременно удаляйте отцветшее, чтобы растение вкладывалось в новые бутоны, а не в семена.',
        '- Наберитесь терпения: многим растениям нужно просто дорасти до возраста цветения.'],
    zh:['叶子长得漂亮却死活不开花的植株，几乎总是光照不足或氮肥过多。',
        '- 开花消耗的能量远高于长叶。几乎所有开花类室内植物都需要明亮光照才「负担得起」。',
        '- 生长季请从均衡肥改为高钾肥（番茄肥就非常合适）。',
        '- 停止高氮施肥——它会让枝叶疯长，而这正是以花苞为代价的。',
        '- 很多种类需要「触发条件」：兰花在夜温比日温低约 10°C 的条件下持续两周后便会复花。秋天把蝴蝶兰放到凉爽的窗边即可。',
        '- 根系稍微满盆反而能促使兰花、白鹤芋与非洲堇开花——不要急着换盆。',
        '- 及时摘除残花，让植株把养分投向新花苞而不是结籽。',
        '- 请耐心等待。许多植物必须先长到一定成熟度，才可能开花。'],
    ar:['النبتة التي تنتج أوراقًا جميلة لكنها ترفض الإزهار تعاني غالبًا من قلة الضوء أو كثرة النيتروجين.',
        '- الإزهار يكلّف طاقة أكبر بكثير من الأوراق، ولهذا تحتاج معظم النباتات المزهرة ضوءًا ساطعًا لتتحمّل كلفته.',
        '- انتقل في موسم النمو من سماد متوازن إلى سماد عالي البوتاسيوم (سماد الطماطم ممتاز لهذا الغرض).',
        '- أوقف التسميد الغني بالنيتروجين، فهو يدفع نموًا ورقيًا غزيرًا على حساب البراعم مباشرة.',
        '- تحتاج أنواع كثيرة محفّزًا: فالأوركيد يعاود الإزهار بعد أسبوعين من ليالٍ أبرد من النهار بنحو ١٠ درجات. ضع الفالاينوبسيس قرب نافذة باردة في الخريف.',
        '- الانحصار الطفيف للجذور يشجّع الإزهار في الأوركيد وزنبق السلام والبنفسج الأفريقي — فلا تتعجّل تغيير أصصها.',
        '- أزِل الأزهار الذابلة فورًا كي تستثمر النبتة في براعم جديدة بدل إنتاج البذور.',
        '- وتحلَّ بالصبر؛ فكثير من النباتات تحتاج ببساطة أن تبلغ نضجًا معيّنًا قبل أن يصبح الإزهار ممكنًا أصلًا.'] } });

P({ id:'winter', cat:'environment',
  kw:{ en:['winter','cold','dormant','dormancy','heating','frost','season change'],
       uz:['qish','sovuq','tinim','uyqu','isitish','ayoz','mavsum'],
       ru:['зим','холод','покой','спячка','отопление','мороз','сезон'],
       zh:['冬天','冬季','寒冷','休眠','暖气','霜','季节'],
       ar:['شتاء','برد','سكون','خمول','تدفئة','صقيع','موسم'] },
  title:{ en:'Winter care', uz:'Qishki parvarish', ru:'Уход зимой', zh:'冬季养护', ar:'العناية الشتوية' },
  body:{
    en:['From November to February most houseplants are barely growing. Caring for them exactly as you did in summer is what kills them.',
        '- Halve the watering. A plant that drank weekly in July may want water only every two or three weeks in January.',
        '- Stop fertilising completely until you see new growth in spring.',
        '- Move plants closer to windows — winter light is a fraction of summer light, even in the same spot.',
        '- But keep leaves off cold glass overnight, and away from draughty window frames. Contact with freezing glass causes black patches.',
        '- Keep them away from radiators and hot-air vents, which create desert-dry air and scorch leaf edges.',
        '- Expect some leaf loss and no new growth. That is dormancy, not failure.',
        '- Clean dust off the leaves with a damp cloth. In low winter light, every bit of photosynthesis counts.'],
    uz:['Noyabrdan fevralgacha ko‘pchilik xonaki o‘simlik deyarli o‘smaydi. Ularni yozdagidek parvarish qilish aynan nobud qiladi.',
        '- Sug‘orishni ikki barobar kamaytiring. Iyulda haftada bir suv ichgan o‘simlikka yanvarda ikki-uch haftada bir marta yetishi mumkin.',
        '- Bahorda yangi o‘sish ko‘rinmaguncha o‘g‘itlashni butunlay to‘xtating.',
        '- O‘simliklarni derazaga yaqinlashtiring — qishki yorug‘lik hatto o‘sha joyda ham yozgisining kichik qismi xolos.',
        '- Lekin kechasi barglar sovuq oynaga tegmasin va shamol o‘tadigan deraza romlaridan uzoq tursin. Muzdek oynaga tegish qora dog‘lar paydo qiladi.',
        '- Ularni radiator va issiq havo teshiklaridan uzoqda saqlang: ular cho‘ldek quruq havo yaratib, barg chetini kuydiradi.',
        '- Bir oz barg to‘kilishi va o‘sishning yo‘qligi kutiladi. Bu tinim davri, muvaffaqiyatsizlik emas.',
        '- Barglardagi changni nam mato bilan arting. Qishki kam yorug‘likda fotosintezning har zarrasi muhim.'],
    ru:['С ноября по февраль большинство комнатных растений почти не растут. Ухаживать за ними как летом — верный способ погубить.',
        '- Сократите полив вдвое. Растение, пившее еженедельно в июле, в январе может требовать воды раз в две-три недели.',
        '- Полностью прекратите подкормки до появления нового прироста весной.',
        '- Переставьте растения ближе к окнам — зимний свет составляет лишь малую долю летнего даже на том же месте.',
        '- Но не позволяйте листьям ночевать на холодном стекле и держите растения подальше от продуваемых рам: контакт с ледяным стеклом даёт чёрные пятна.',
        '- Держите их подальше от батарей и потоков горячего воздуха — они создают пустынно-сухой воздух и сжигают края листьев.',
        '- Небольшое опадение листьев и отсутствие роста — это норма. Так выглядит покой, а не неудача.',
        '- Протирайте пыль с листьев влажной тканью: при скудном зимнем свете важен каждый процент фотосинтеза.'],
    zh:['十一月到二月，大多数室内植物几乎停止生长。像夏天那样照顾它们，恰恰会把它们养死。',
        '- 浇水减半。七月每周要喝水的植株，一月可能两三周才需要一次。',
        '- 彻底停肥，直到春天看到新芽为止。',
        '- 把植物移得更靠近窗户——即便位置不变，冬季光照也只有夏季的一小部分。',
        '- 但夜间别让叶片贴着冰冷的玻璃，也要远离漏风的窗框。接触冰玻璃会产生黑斑。',
        '- 远离暖气片与热风出风口，它们制造沙漠般干燥的空气并灼伤叶缘。',
        '- 掉几片叶、不长新叶都是正常的。这是休眠，不是养失败。',
        '- 用湿布擦去叶面灰尘。在冬季的弱光下，每一分光合作用都很重要。'],
    ar:['من نوفمبر إلى فبراير تكاد معظم النباتات المنزلية لا تنمو. والاعتناء بها تمامًا كما في الصيف هو ما يقتلها.',
        '- خفّض الري إلى النصف. فالنبتة التي كانت تُسقى أسبوعيًا في يوليو قد تحتاج الماء كل أسبوعين أو ثلاثة في يناير.',
        '- أوقف التسميد تمامًا حتى ترى نموًا جديدًا في الربيع.',
        '- قرّب النباتات من النوافذ — فضوء الشتاء جزء يسير من ضوء الصيف حتى في المكان نفسه.',
        '- لكن أبعد الأوراق عن ملامسة الزجاج البارد ليلًا، وعن إطارات النوافذ التي يتسرّب منها الهواء؛ فملامسة الزجاج المتجمّد تسبّب بقعًا سوداء.',
        '- أبعدها عن المشعّات وفتحات الهواء الساخن، فهي تصنع هواءً جافًا كالصحراء وتحرق حواف الأوراق.',
        '- توقّع فقدان بعض الأوراق وغياب النمو الجديد. هذا سكون موسمي وليس فشلًا.',
        '- امسح الغبار عن الأوراق بقطعة قماش مبللة؛ ففي ضوء الشتاء الشحيح كل قدر من التمثيل الضوئي مهم.'] } });

P({ id:'vacation', cat:'environment',
  kw:{ en:['holiday','vacation','away','travel','two weeks away','who waters','self watering'],
       uz:['tatil','safar','yoq bolaman','yo‘q bo‘laman','sayohat','kim sugoradi'],
       ru:['отпуск','уеду','отъезд','путешеств','кто польёт','автополив'],
       zh:['度假','出差','出门','旅行','没人浇','自动浇水'],
       ar:['إجازة','سفر','سأغيب','من يسقي','ري ذاتي'] },
  title:{ en:'Leaving plants while you travel', uz:'Safar paytida o‘simliklarni qoldirish', ru:'Растения на время отъезда', zh:'出门旅行时如何照料植物', ar:'ترك النباتات أثناء السفر' },
  body:{
    en:['Most houseplants survive two weeks alone with no special equipment. Three weeks or more needs a plan.',
        '- Water everything thoroughly the morning you leave, and let the pots drain completely.',
        '- Move every plant away from windows into the middle of the room. Less light means less water used — they will simply pause.',
        '- Group them together on a tray. The shared humidity slows evaporation for all of them.',
        '- For three weeks or more, stand pots on a capillary mat with one end in a basin of water, or use ceramic watering spikes attached to a bottle.',
        '- Succulents, cacti, snake plants and ZZ plants need nothing at all for a month.',
        '- Thirsty plants — ferns, basil, calatheas — are the ones to give to a neighbour.',
        '- Do not fertilise before leaving, and never leave plants standing in a tray of water to keep them going. That rots roots within days.'],
    uz:['Ko‘pchilik xonaki o‘simlik hech qanday maxsus jihozsiz ikki hafta yolg‘iz qoladi. Uch hafta va undan ko‘pi reja talab qiladi.',
        '- Jo‘nash kuni ertalab hammasini yaxshilab sug‘oring va tuvaklardagi suv to‘liq oqib ketsin.',
        '- Har bir o‘simlikni derazadan xona o‘rtasiga ko‘chiring. Kam yorug‘lik kam suv degani — ular shunchaki to‘xtab turadi.',
        '- Ularni bitta tovoqqa birga yig‘ing. Umumiy namlik barchasi uchun bug‘lanishni sekinlashtiradi.',
        '- Uch hafta va undan ko‘p bo‘lsa, tuvaklarni bir uchi suvli idishda turgan kapillyar matga qo‘ying yoki shishaga ulanadigan keramik sug‘orish tiqinlaridan foydalaning.',
        '- Sukkulent, kaktus, sansevieriya va zamiokulkasga bir oy davomida umuman hech narsa kerak emas.',
        '- Suvni ko‘p talab qiladiganlarini — paportnik, rayhon, kalateya — qo‘shniga berib keting.',
        '- Jo‘nashdan oldin o‘g‘itlamang va chidasin deb o‘simlikni suvli tovoqda qoldirmang. Bu bir necha kunda ildizni chiritadi.'],
    ru:['Большинство комнатных растений спокойно переживают две недели в одиночестве без всякого оборудования. Три недели и больше требуют плана.',
        '- Утром в день отъезда хорошо полейте всё и дайте горшкам полностью стечь.',
        '- Отодвиньте растения от окон в середину комнаты. Меньше света — меньше расход воды, растения просто поставят рост на паузу.',
        '- Соберите их вместе на одном поддоне: общая влажность замедлит испарение для всех.',
        '- На три недели и дольше поставьте горшки на капиллярный мат, опустив его край в таз с водой, либо используйте керамические конусы с бутылкой.',
        '- Суккулентам, кактусам, сансевиерии и замиокулькасу целый месяц не нужно ничего.',
        '- Самых «пьющих» — папоротники, базилик, калатеи — лучше отдать соседям.',
        '- Не удобряйте перед отъездом и никогда не оставляйте горшки стоять в поддоне с водой «чтобы хватило». Так корни сгниют за несколько дней.'],
    zh:['多数室内植物独自待两周完全没问题，不需要任何特殊设备。三周以上才需要安排。',
        '- 出发当天早上把所有植物浇透，并让盆里的水彻底沥干。',
        '- 把植物从窗边移到房间中央。光少则耗水少——它们只会暂停生长。',
        '- 把它们集中摆在同一个托盘上，共享的湿度能减缓所有植株的水分蒸发。',
        '- 若离开三周以上，可将盆放在毛细吸水垫上、垫子一端浸入水盆，或使用接瓶子的陶瓷浇水插头。',
        '- 多肉、仙人掌、虎尾兰与金钱树整整一个月都不需要任何照料。',
        '- 最「喝水」的那几盆——蕨类、罗勒、竹芋——请托付给邻居。',
        '- 出门前不要施肥，也绝不要为了撑久一点把盆泡在水盘里。那样几天就会烂根。'],
    ar:['تنجو معظم النباتات المنزلية أسبوعين بمفردها دون أي معدّات خاصة. أما ثلاثة أسابيع فأكثر فتحتاج خطة.',
        '- اسقِ كل شيء جيدًا صباح يوم سفرك، ودع الأصص تصرّف ماءها بالكامل.',
        '- انقل كل نبتة بعيدًا عن النوافذ إلى وسط الغرفة. ضوء أقل يعني استهلاك ماء أقل — وستكتفي بالتوقّف مؤقتًا.',
        '- اجمعها معًا على صينية واحدة؛ فالرطوبة المشتركة تبطّئ التبخّر لها جميعًا.',
        '- لثلاثة أسابيع فأكثر، ضع الأصص على حصيرة شعرية طرفها في حوض ماء، أو استخدم مخاريط ري خزفية موصولة بزجاجة.',
        '- العصاريات والصبّار وسانسيفيريا وزاميوكولكاس لا تحتاج شيئًا إطلاقًا لمدة شهر.',
        '- أما النباتات الشرِهة للماء — السرخسيات والريحان والكالاثيا — فهي التي تُعطى للجيران.',
        '- لا تسمّد قبل السفر، ولا تترك الأصص واقفة في صينية ماء كي تصمد؛ فذلك يعفّن الجذور خلال أيام.'] } });

P({ id:'water-quality', cat:'water',
  kw:{ en:['tap water','hard water','filtered water','rainwater','chlorine','fluoride','distilled'],
       uz:['jomrak suvi','jo‘mrak suvi','qattiq suv','filtr suv','yomgir suvi','xlor'],
       ru:['водопроводная вода','жёсткая вода','фильтрованная','дождевая','хлор','фтор','отстаивать'],
       zh:['自来水','硬水','过滤水','雨水','氯','氟','静置'],
       ar:['ماء الصنبور','ماء عسر','ماء مرشّح','ماء المطر','كلور','فلورايد'] },
  title:{ en:'Which water to use', uz:'Qaysi suvdan foydalanish kerak', ru:'Какой водой поливать', zh:'该用什么水浇', ar:'أي ماء تستخدم للري' },
  body:{
    en:['For most plants tap water is perfectly fine. A handful of sensitive species genuinely notice the difference.',
        '- Fussy about water: calathea, maranta, dracaena, spider plant, carnivorous plants and most ferns. Brown tips are the usual complaint.',
        '- Chlorine evaporates if you leave tap water in an open jug overnight. Fluoride and mineral salts do not — those need filtering.',
        '- Rainwater is free, naturally soft and the best option of all. A bucket outside solves the problem permanently.',
        '- Filtered or previously boiled and cooled water is a good substitute. Distilled water works but is overkill for almost everything.',
        '- Use room-temperature water. Cold water straight from the tap shocks tropical roots and can cause leaf spotting.',
        '- Softened water from an ion-exchange softener is the one to avoid — it is high in sodium, which damages roots over time.'],
    uz:['Ko‘pchilik o‘simlik uchun jo‘mrak suvi mutlaqo yaroqli. Bir nechta sezgir tur esa farqni haqiqatan sezadi.',
        '- Suvga talabchanlar: kalateya, maranta, dratsena, xlorofitum, yirtqich o‘simliklar va ko‘pchilik paportniklar. Odatdagi shikoyat — jigarrang uchlar.',
        '- Jo‘mrak suvini ochiq idishda bir kecha qoldirsangiz, xlor uchib ketadi. Ftor va mineral tuzlar esa yo‘q — ular filtrlashni talab qiladi.',
        '- Yomg‘ir suvi bepul, tabiiy yumshoq va eng yaxshi variant. Tashqariga qo‘yilgan chelak muammoni butunlay hal qiladi.',
        '- Filtrlangan yoki qaynatib sovutilgan suv yaxshi almashtiruvchi. Distillangan suv ishlaydi, lekin deyarli hamma narsa uchun ortiqcha.',
        '- Xona haroratidagi suvdan foydalaning. Jo‘mrakdan to‘g‘ridan olingan sovuq suv tropik ildizlarni shokka soladi va bargda dog‘ paydo qilishi mumkin.',
        '- Ion almashinuvli yumshatgichdan chiqqan suvdan qoching — unda natriy ko‘p, bu vaqt o‘tishi bilan ildizni shikastlaydi.'],
    ru:['Для большинства растений водопроводная вода вполне подходит. Но несколько чувствительных видов действительно замечают разницу.',
        '- Придирчивы к воде: калатея, маранта, драцена, хлорофитум, насекомоядные и большинство папоротников. Типичная жалоба — коричневые кончики.',
        '- Хлор улетучивается, если оставить воду в открытом кувшине на ночь. Фтор и минеральные соли — нет, их нужно отфильтровывать.',
        '- Дождевая вода бесплатна, естественно мягкая и лучше всех. Ведро на улице решает вопрос навсегда.',
        '- Фильтрованная или прокипячённая и остывшая вода — хорошая замена. Дистиллированная тоже годится, но для большинства растений это излишне.',
        '- Поливайте водой комнатной температуры. Холодная вода прямо из-под крана шокирует тропические корни и вызывает пятна на листьях.',
        '- Единственное, чего стоит избегать, — вода из ионообменного умягчителя: в ней много натрия, который со временем повреждает корни.'],
    zh:['对大多数植物来说，自来水完全够用。只有少数敏感物种确实能感觉到差别。',
        '- 对水质挑剔的有：竹芋、肖竹芋、龙血树、吊兰、食虫植物与多数蕨类，常见表现就是叶尖发褐。',
        '- 把自来水敞口静置一夜，氯会挥发；但氟和矿物盐不会——那需要过滤。',
        '- 雨水免费、天然软水，是最佳选择。在室外放一个水桶就能一劳永逸。',
        '- 过滤水或煮沸放凉的水是不错的替代。蒸馏水也行，但对绝大多数植物属于杀鸡用牛刀。',
        '- 请用室温水。直接接的冷水会让热带植物的根受冲击，并可能导致叶片出现斑点。',
        '- 唯一要避免的是离子交换软水机出来的水——钠含量高，长期会损伤根系。'],
    ar:['ماء الصنبور مناسب تمامًا لمعظم النباتات. لكن قلة من الأنواع الحسّاسة تلاحظ الفرق فعلًا.',
        '- الأنواع المتذمّرة من الماء: الكالاثيا والمارانتا والدراسينا ونبات العنكبوت والنباتات آكلة الحشرات ومعظم السرخسيات، والشكوى المعتادة هي الأطراف البنية.',
        '- يتبخّر الكلور إذا تركت ماء الصنبور في إبريق مفتوح ليلة كاملة، أما الفلورايد والأملاح المعدنية فلا — وهذه تحتاج ترشيحًا.',
        '- ماء المطر مجاني وطبيعي العذوبة وهو الخيار الأفضل على الإطلاق. ودلو في الخارج يحلّ المسألة نهائيًا.',
        '- الماء المرشّح أو المغلي ثم المبرّد بديل جيد. والماء المقطّر يعمل لكنه مبالغة لمعظم الحالات.',
        '- استخدم ماءً بدرجة حرارة الغرفة؛ فالماء البارد مباشرة من الصنبور يصدم الجذور الاستوائية وقد يسبّب تبقّع الأوراق.',
        '- أما ما يجب تجنّبه فهو ماء مُليّنات التبادل الأيوني — فهو غني بالصوديوم الذي يضرّ الجذور مع الوقت.'] } });

P({ id:'sunburn', cat:'problem',
  kw:{ en:['sunburn','scorch','burnt leaves','bleached','white patches','too much sun','faded leaves'],
       uz:['kuyish','kuygan barg','oqarib ketgan','oq dog','kop quyosh','ko‘p quyosh'],
       ru:['солнечный ожог','ожог','обожжённые листья','выгорели','белые пятна','много солнца'],
       zh:['日灼','晒伤','叶片发白','褪色','白斑','太阳太强'],
       ar:['حروق شمس','احتراق','أوراق محترقة','بقع بيضاء','شمس قوية'] },
  title:{ en:'Sunburn and scorched leaves', uz:'Quyosh kuydirishi va kuygan barglar', ru:'Солнечный ожог листьев', zh:'日灼与叶片灼伤', ar:'حروق الشمس واحتراق الأوراق' },
  body:{
    en:['Sunburn appears as pale, bleached or crisp brown patches in the middle of leaves, on the side facing the window.',
        '- Unlike disease, the damage appears suddenly, affects only the most exposed leaves, and never spreads.',
        '- The usual cause is a sudden change — a plant moved from a shaded shop or a dim corner straight into direct midday sun.',
        '- Move the plant back from the glass by a metre, or hang a sheer curtain to diffuse the light.',
        '- Burnt tissue never recovers. Leave the leaf in place unless it is more than half damaged — it still photosynthesises.',
        '- Acclimatise gradually: when increasing light, do it over two to three weeks, an hour more exposure at a time.',
        '- Glass magnifies heat, so a leaf touching a sunny window burns even when the room feels comfortable.',
        '- Succulents and cacti can sunburn too, especially after a dim winter indoors.'],
    uz:['Quyosh kuydirishi bargning o‘rtasida, derazaga qaragan tomonida oqargan yoki qurib jigarrang bo‘lgan dog‘lar shaklida ko‘rinadi.',
        '- Kasallikdan farqli ravishda, zarar to‘satdan paydo bo‘ladi, faqat eng ochiq barglarga ta’sir qiladi va hech qachon tarqalmaydi.',
        '- Odatiy sabab — keskin o‘zgarish: soyali do‘kondan yoki xira burchakdan to‘g‘ridan-to‘g‘ri tush quyoshiga ko‘chirish.',
        '- O‘simlikni oynadan bir metr nariga suring yoki yorug‘likni tarqatish uchun yupqa parda osing.',
        '- Kuygan to‘qima tiklanmaydi. Barg yarmidan ko‘pi shikastlanmagan bo‘lsa, uni olib tashlamang — u hali ham fotosintez qiladi.',
        '- Asta-sekin moslashtiring: yorug‘likni oshirganda, buni ikki-uch hafta davomida, har safar bir soatga ko‘paytirib qiling.',
        '- Oyna issiqlikni kuchaytiradi, shuning uchun quyoshli oynaga tegib turgan barg xona qulay tuyulsa ham kuyadi.',
        '- Sukkulent va kaktuslar ham kuyishi mumkin, ayniqsa xira qishdan keyin.'],
    ru:['Солнечный ожог выглядит как бледные, выгоревшие или сухие бурые пятна в середине листа, с той стороны, что обращена к окну.',
        '- В отличие от болезни, повреждение появляется внезапно, затрагивает только самые открытые листья и никогда не распространяется.',
        '- Обычная причина — резкая перемена: растение переехало из затенённого магазина или тёмного угла прямо под полуденное солнце.',
        '- Отодвиньте растение от стекла на метр или повесьте лёгкую занавеску, рассеивающую свет.',
        '- Обожжённая ткань не восстанавливается. Не срезайте лист, если повреждено меньше половины: он всё ещё фотосинтезирует.',
        '- Приучайте постепенно: увеличивая свет, растягивайте это на две-три недели, добавляя по часу экспозиции.',
        '- Стекло усиливает нагрев, поэтому лист, прижатый к солнечному окну, обгорает даже когда в комнате комфортно.',
        '- Суккуленты и кактусы тоже обгорают, особенно после тёмной зимы в помещении.'],
    zh:['日灼表现为叶片中部出现发白、褪色或干枯发褐的斑块，且集中在朝向窗户的一侧。',
        '- 与病害不同，这种损伤突然出现，只影响受光最强的叶片，而且绝不扩散。',
        '- 常见原因是环境骤变——植株从阴凉的花店或昏暗角落直接搬到正午烈日下。',
        '- 把植株从玻璃旁退后一米，或挂一层薄纱帘来柔化光线。',
        '- 灼伤的组织不会恢复。只要受损面积不超过一半，就把叶子留着——它仍在进行光合作用。',
        '- 请循序渐进：需要增加光照时，分两到三周完成，每次多晒一小时。',
        '- 玻璃会聚热，所以即便房间体感舒适，紧贴向阳玻璃的叶片仍会被灼伤。',
        '- 多肉和仙人掌同样会日灼，尤其在室内度过昏暗的冬季之后。'],
    ar:['تظهر حروق الشمس كبقع شاحبة أو مُبيَّضة أو بنية هشّة في وسط الأوراق، على الجهة المواجهة للنافذة.',
        '- وخلافًا للأمراض، يظهر الضرر فجأة ويصيب الأوراق الأكثر تعرّضًا فقط، ولا ينتشر أبدًا.',
        '- والسبب المعتاد تغيير مفاجئ: نبتة نُقلت من متجر مظلّل أو ركن خافت إلى شمس الظهيرة المباشرة.',
        '- أبعد النبتة عن الزجاج مسافة متر، أو علّق ستارة شفافة لتشتيت الضوء.',
        '- الأنسجة المحترقة لا تتعافى. اترك الورقة في مكانها ما لم يتجاوز التلف نصفها — فهي ما زالت تقوم بالتمثيل الضوئي.',
        '- أقلِم النبتة تدريجيًا: عند زيادة الضوء، وزّع ذلك على أسبوعين إلى ثلاثة، بساعة إضافية في كل مرة.',
        '- الزجاج يضاعف الحرارة، لذا تحترق الورقة الملامسة لنافذة مشمسة حتى لو كانت الغرفة مريحة.',
        '- والعصاريات والصبّار تحترق أيضًا، خصوصًا بعد شتاء داخلي خافت الإضاءة.'] } });

})(window.KB);
